INSERT INTO missions (id, text) VALUES
  (1, 'Fai un brindisi in rima a Matteo che contenga la parola “tesi”, il nome di Enrico e un ananas. Almeno tre persone devono alzare il bicchiere.'),
  (2, 'Racconta a qualcuno la tesi di Matteo come se fosse la trama di un film d''azione. Chi ti ascolta deve chiederti come va a finire.'),
  (3, 'Inventa un soprannome segreto che Matteo avrebbe avuto all''università e fallo credere a qualcuno. Prima della fine della serata un''altra persona deve usarlo davanti a te.'),
  (4, 'Convinci Enrico a chiamare Matteo “Ingegnere” almeno 3 volte nello stesso discorso, senza chiederglielo.'),
  (5, 'Fai partire un applauso per Matteo dicendo ad alta voce una frase senza senso. Non puoi chiedere di applaudire e non puoi essere il primo a battere le mani.'),
  (6, 'Spiega a Enrico l''argomento della tesi di Matteo usando solo gesti.'),
  (7, 'Davanti a un gruppo, fai un complimento a tre invitati diversi, ognuno più specifico e assurdo del precedente. Almeno uno deve ringraziarti sinceramente.'),
  (8, 'Avvia una discussione seria su una questione inutile, come stabilire se i ravioli siano pasta o un contenitore commestibile. Almeno quattro invitati devono prendere posizione.'),
  (9, 'Convinci due persone che non stanno parlando tra loro a raccontarti, ciascuna, un motivo per cui Enrico meriterebbe di diventare famoso.'),
  (10, 'Sostieni per almeno un minuto una teoria palesemente assurda con il tono di un professore universitario. Almeno una persona deve farti una domanda seria.'),
  (11, 'Fai fare una foto di gruppo con almeno 5 persone, ma deve proporla qualcun altro e almeno 3 persone devono fare una faccia stupida.'),
  (12, 'Fai scambiare un complimento a due persone che si conoscono poco, senza dire che è la tua missione. Poi devono brindare insieme.'),
  (13, 'Fai un discorso motivazionale a un invitato su un''attività banale, come prendere da bere o scegliere dove sedersi. Chiudi con una frase memorabile che lui deve ripetere.'),
  (14, 'Durante una conversazione, inserisci le parole “satellite”, “pizza” e “Genti” nella stessa frase, senza che nessuno ti chieda perché le hai dette.'),
  (15, 'Per tutta la serata non dire mai “sì” né “no”. Se qualcuno ti becca a dirlo, la missione è fallita.'),
  (16, 'Fai dire a qualcuno una cattiveria sulla tesi di Matteo, senza chiederglielo.'),
  (17, 'Fai partire un trenino con almeno sei persone. Non puoi proporlo tu: deve sembrare un''idea di qualcun altro.'),
  (18, 'Fai pronunciare la parola “antenna” a 3 persone diverse, in conversazioni separate, senza chiederglielo.'),
  (19, 'Convinci Zizzo a fare una foto con Matteo in una posa inventata da te, senza dirgli che l''hai inventata tu.'),
  (20, 'Fai imitare a Enrico la risata di Matti davanti ad almeno 6 persone, senza chiederglielo.'),
  (21, 'Fai dire a Enrico “non è scontato per niente” durante una conversazione che non parli di università, studio o lavoro.'),
  (22, 'Ogni volta che vedi qualcuno con il bicchiere vuoto, convincilo a riempirlo.'),
  (23, 'Convinci qualcuno a fare un brindisi a Matteo paragonandolo a un elettrodomestico, spiegando anche perché.'),
  (24, 'Fai partire un coro da stadio per Matteo (se non ne conosci uno, trova Galli e fattelo insegnare). Almeno cinque persone devono seguirti.'),
  (25, 'Ogni volta che incroci Enrico, fagli i complimenti per come è vestito. Almeno una volta deve chiederti se lo stai prendendo in giro.'),
  (26, 'Hai un alleato segreto: un solo altro invitato ha questa stessa missione. Trovalo senza farti scoprire e insieme organizzate uno scherzo a Pippo prima della fine della serata.'),
  (27, 'Hai un alleato segreto: un solo altro invitato ha questa stessa missione. Trovalo senza farti scoprire e insieme organizzate uno scherzo a Pippo prima della fine della serata.'),
  (28, 'Trova una persona che conosce Matteo da molto tempo e convincila a raccontare, davanti ad almeno altre due persone, un episodio che Matteo preferirebbe restasse segreto.'),
  (29, 'Fai dire a Enrico “Questa è stata una bella idea” senza mai fargli capire che stai facendo una missione.'),
  (30, 'Convinci Galli a raccontare la storia di quando ha incontrato una persona a Rosciano a cui nessuno crederà mai'),
  (31, 'Convinci Galli a raccontare la storia di quando ha incontrato una persona a Rosciano a cui nessuno crederà mai')
